import os

def find_symlinks_and_dirs(root):
    links = []
    dirs = []
    for dirpath, dirnames, filenames in os.walk(root):
        for d in dirnames:
            p = os.path.join(dirpath, d)
            if os.path.islink(p):
                print("Symlink dir:", p)
            dirs.append(p)
        for f in filenames:
            p = os.path.join(dirpath, f)
            if os.path.islink(p):
                links.append(p)
    return links, dirs

